"""Offline full Settings handler audit with no desktop, auth, or network access."""
import re
import subprocess
from pathlib import Path

SOURCE = Path(__file__).parents[1] / "src/voice_flow/gui/app.js"
HTML = SOURCE.with_name("index.html")


def test_settings_inline_handlers_exist():
    html = HTML.read_text(encoding="utf-8")
    start = html.index('id="settings-modal"')
    end = html.index('<!-- SETTINGS SUB-MODAL: MICROPHONE -->', start)
    handlers = set(re.findall(r'(?:onclick|onchange)="([^"]+)"', html[start:end]))
    names = {name for handler in handlers for name in re.findall(r"([A-Za-z_$][\w$]*)\(", handler) if name not in {"if"}}
    source = SOURCE.read_text(encoding="utf-8")
    missing = sorted(name for name in names if not re.search(r"(?:function\s+" + re.escape(name) + r"\s*\(|(?:const|let|var)\s+" + re.escape(name) + r"\s*=)", source))
    assert not missing, missing


def test_settings_handlers_offline():
    harness = r"""
const fs=require('fs'),vm=require('vm'),assert=require('assert');
const source=fs.readFileSync(process.argv[1],'utf8').replace(/\r\n/g,'\n');
function slice(a,b){const start=source.indexOf(a),end=source.indexOf(b,start);assert(start>=0&&end>start);return source.slice(start,end)}
const nodes=new Map(),calls=[],toasts=[],timers=[],store=new Map();
function node(id){if(!nodes.has(id)){const classes=new Set();nodes.set(id,{checked:false,disabled:false,textContent:'',innerHTML:'',style:{},parentElement:{style:{}},className:'',classList:{add(x){classes.add(x)},remove(x){classes.delete(x)},contains(x){return classes.has(x)},toggle(x,v){v?classes.add(x):classes.delete(x)}},getAttribute(k){return this[k]||''},setAttribute(k,v){this[k]=v}})}return nodes.get(id)}
let request=async()=>({success:false,error:'Refused'}),fetchRequest=async()=>({ok:false,json:async()=>({success:false,error:'Refused'})});
const context={document:{documentElement:node('document-root'),getElementById:node,querySelectorAll(){return []}},window:{location:{reload(){calls.push('reload')}},vfPlatformInfo:{}},localStorage:{getItem:k=>store.get(k)||null,setItem:(k,v)=>store.set(k,v)},console:{warn(){},error(){},debug(){}},safeFetchJson:async(u,o)=>{calls.push({url:u,options:o});return request(u,o)},fetch:async(u,o)=>{calls.push({url:u,options:o});return fetchRequest(u,o)},vfToast:(...a)=>toasts.push(a),showToast:(...a)=>toasts.push(a),vfAlert:(...a)=>toasts.push(a),vfConfirm:async()=>true,setTimeout:f=>{timers.push(f);return timers.length},setInterval:f=>{timers.push(f);return timers.length},clearTimeout(){},clearInterval(){},loadHotkeySettings(){},loadHardwareMicrophones(){},closeSubModal(id){node(id).classList.add('hidden')},reloadAllApplicationMemory(){calls.push('reload-memory')},escapeHtml:x=>String(x),Date,encodeURIComponent};
vm.createContext(context);
for(const code of [slice('async function showFloatingOverlay()', 'async function initOverlayControl()'),slice('// Settings Modal Controls','async function copyToClipboard('),slice('async function toggleClickToPasteSetting(', 'async function toggleVideoFlowFeature('),slice('let currentAccountData = null;', 'function reloadAllApplicationMemory()'),slice('function applyTheme(', '// Settings Modal Controls'),slice('async function checkForAppUpdates(', '\ntry {\n  setTimeout(')])vm.runInContext(code,context);
async function flush(){for(let i=0;i<8;i++)await Promise.resolve()}
(async()=>{const failures=[];async function check(name,f){calls.length=0;toasts.length=0;timers.length=0;request=async()=>({success:false,error:'Refused'});fetchRequest=async()=>({ok:false,json:async()=>({success:false,error:'Refused'})});try{await f()}catch(e){failures.push(name+': '+e.message)}}
await check('click-to-paste failed response preserves switch and no success',async()=>{node('toggle-click-to-paste').checked=true;await context.toggleClickToPasteSetting(true);assert.equal(node('toggle-click-to-paste').checked,false);assert(!toasts.some(t=>String(t[0]).includes('ON')))});
await check('popup theme failure preserves saved local and UI state',async()=>{store.set('on_screen_ui_theme','light');node('toggle-on-screen-ui-theme').checked=true;await context.toggleOnScreenUITheme(true);assert.equal(store.get('on_screen_ui_theme'),'light');assert.equal(node('toggle-on-screen-ui-theme').checked,false);assert(!toasts.some(t=>String(t[0]).includes('set to')))});
await check('cache failed response and throw never report cleared',async()=>{await context.clearAudioRecordingsCache();assert(!toasts.some(t=>/cleared/i.test(t[0])&&!t[1]));toasts.length=0;request=async()=>{throw Error('offline')};await context.clearAudioRecordingsCache();assert(!toasts.some(t=>/cleared/i.test(t[0])&&!t[1]))});
await check('deep restart refusal does not reload page',async()=>{await context.triggerDeepAppRestart();for(const timer of timers)timer();assert(!calls.includes('reload'))});
await check('signout refused response does not claim signed out',async()=>{await context.handleSimpleSignOut();assert(!toasts.some(t=>t[0]==='Signed out.'));assert(!calls.includes('reload-memory'))});
await check('late preference GET cannot erase completed toggle',async()=>{let finish;request=(u,o)=>o?Promise.resolve({success:true}):u.includes('click_to_paste_enabled')?new Promise(resolve=>finish=resolve):Promise.resolve({success:true,value:false,enabled:false});context.openSettings();node('toggle-click-to-paste').checked=true;await context.toggleClickToPasteSetting(true);finish({success:true,value:false});await flush();assert.equal(node('toggle-click-to-paste').checked,true)});
await check('old account status cannot overwrite newest account',async()=>{let finish;request=()=>new Promise(resolve=>finish=resolve);const old=context.loadAccountSettingsView();request=async()=>({success:true,authenticated:true,active_account:{id:'B',email:'b@example.test',username:'B'},accounts:[]});await context.loadAccountSettingsView();finish({success:true,authenticated:true,active_account:{id:'A',email:'a@example.test',username:'A'},accounts:[]});await old;assert.equal(node('account-current-name').textContent,'B')});
await check('closing Settings also closes child shortcut and mic dialogs',async()=>{node('shortcuts-sub-modal').classList.remove('hidden');node('mic-sub-modal').classList.remove('hidden');await context.closeSettings();assert(node('shortcuts-sub-modal').classList.contains('hidden'));assert(node('mic-sub-modal').classList.contains('hidden'))});
await check('late autostart status cannot erase successful toggle',async()=>{let finish;request=(u,o)=>o?Promise.resolve({success:true,enabled:true}):new Promise(resolve=>finish=resolve);const loading=context.checkAutoStartStatus();node('toggle-autostart').checked=true;await context.toggleAutoStartSetting(true);finish({success:true,enabled:false});await loading;assert(node('toggle-autostart').checked)});
await check('taskbar saved but apply failure retains persisted preference',async()=>{request=async()=>({success:false,saved:true,value:false,error:'Native apply unavailable'});node('toggle-show-in-taskbar').checked=false;await context.toggleShowInTaskbarSetting(false);assert.equal(node('toggle-show-in-taskbar').checked,false);assert(toasts.some(t=>t[1]))});
await check('taskbar duplicate requests serialized',async()=>{let finish;request=()=>new Promise(resolve=>finish=resolve);const first=context.toggleShowInTaskbarSetting(false);const second=context.toggleShowInTaskbarSetting(true);assert.equal(calls.filter(c=>c.url==='/api/settings/update').length,1);finish({success:true,value:false});await first;await second});
await check('older update check cannot erase newest result',async()=>{let finish;fetchRequest=()=>new Promise(resolve=>finish=resolve);const old=context.checkForAppUpdates(true);fetchRequest=async()=>({ok:true,json:async()=>({success:true,update_available:true,latest_version:'2.0.0',release_url:'https://example.test/release'})});const recent=context.checkForAppUpdates(true);await flush();if(calls.length===1){finish({ok:true,json:async()=>({success:true,update_available:true,latest_version:'2.0.0',release_url:'https://example.test/release'})});await old;await recent;}else{await recent;finish({ok:true,json:async()=>({success:true,update_available:false,current_version:'1.0.0'})});await old;}assert(node('update-status-message').innerHTML.includes('2.0.0'))});
await check('Google polling has one request in flight',async()=>{fetchRequest=async()=>({ok:true,json:async()=>({success:true,pair_token:'offline-token'})});await context.handleGoogleAccountSignIn();const poll=timers.at(-1);let finish;fetchRequest=()=>new Promise(resolve=>finish=resolve);const first=poll();const second=poll();await flush();assert.equal(calls.filter(c=>c.url.includes('/google/status')).length,1);finish({ok:true,json:async()=>({success:true,claimed:false})});await first;await second;context.closeSettings()});
await check('closed Settings ignores stale Google poll success',async()=>{fetchRequest=async()=>({ok:true,json:async()=>({success:true,pair_token:'offline-token'})});await context.handleGoogleAccountSignIn();const poll=timers.at(-1);let finish;fetchRequest=()=>new Promise(resolve=>finish=resolve);const pending=poll();await context.closeSettings();finish({ok:true,json:async()=>({success:true,claimed:true,active_account:{username:'Stale'}})});await pending;assert(!toasts.some(t=>String(t[0]).includes('Signed in as Stale')))});
await check('dashboard theme failure never claims saved and restores state',async()=>{node('document-root').setAttribute('data-theme','light');store.set('vf-theme','light');await context.toggleTheme();await flush();assert.equal(node('document-root').getAttribute('data-theme'),'light');assert(!toasts.some(t=>String(t[0]).includes('(saved)')))});
await check('server theme bootstrap authoritative without writing local account theme',async()=>{store.set('vf-theme','dark');fetchRequest=async()=>({ok:true,json:async()=>({success:true,theme:'light'})});vm.runInContext(slice('(async function bootstrapTheme()', '// Settings Modal Controls'),context);await flush();assert.equal(node('document-root').getAttribute('data-theme'),'light');assert(!calls.some(c=>c.options?.method==='POST'&&c.url==='/api/settings/theme'))});
await check('closed Settings ignores pending Google sign-in start',async()=>{let finish;fetchRequest=()=>new Promise(resolve=>finish=resolve);const pending=context.handleGoogleAccountSignIn();await context.closeSettings();finish({ok:true,json:async()=>({success:true,pair_token:'closed-token'})});await pending;assert.equal(timers.length,0);assert(!node('btn-google-signin').disabled)});
await check('real helper rejects non-OK success body and preserves saved status',async()=>{const helper={fetch:async()=>({ok:false,status:503,text:async()=>JSON.stringify({success:true,saved:true,enabled:true})}),console:context.console};vm.createContext(helper);vm.runInContext(slice('async function safeFetchJson(', 'if (typeof window !== "undefined")'),helper);const result=await helper.safeFetchJson('/mock');assert.equal(result.success,false);assert.equal(result.saved,true);assert.equal(result.status,503);assert.equal(result.ok,false);assert(result.error.includes("503"))});
await check('closed Settings ignores pending autostart result',async()=>{let finish;request=()=>new Promise(resolve=>finish=resolve);const pending=context.toggleAutoStartSetting(false);await context.closeSettings();node('toggle-autostart').checked=true;finish({success:true,enabled:false});await pending;assert(node('toggle-autostart').checked);assert(!toasts.some(t=>String(t[0]).includes('Auto-startup')))});
await check('autostart rollback failure displays actual startup state',async()=>{request=async()=>({success:false,saved:false,enabled:true,error:'Rollback failed'});node('toggle-autostart').checked=true;await context.toggleAutoStartSetting(true);assert(node('toggle-autostart').checked);assert(toasts.some(t=>t[1]))});
await check('unknown autostart rollback state stays unavailable until status reload',async()=>{request=async()=>({success:false,saved:false,enabled:null,error:'Native status unknown'});await context.toggleAutoStartSetting(false);assert.equal(node('autostart-status-badge').textContent,'Unavailable');assert(node('toggle-autostart').disabled);request=async()=>({success:true,enabled:true});await context.checkAutoStartStatus();assert(!node('toggle-autostart').disabled);assert(node('toggle-autostart').checked)});
if(failures.length)throw Error(failures.join('\n'));
})().catch(e=>{process.stderr.write(String(e)+'\n');process.exitCode=1});
"""
    result = subprocess.run(["node", "-e", harness, str(SOURCE)], capture_output=True, text=True)
    assert result.returncode == 0, result.stderr
